int process_protocol_message(const char* msg_body, int body_len, char* param_buffer, int buffer_size) {
    // 检查输入参数的有效性
    if (msg_body == NULL || param_buffer == NULL || body_len < 0 || buffer_size <= 0) {
        return -1; // 参数错误
    }

    // 确保消息体长度不会导致缓冲区溢出
    int copy_len = body_len;
    if (copy_len >= buffer_size) {
        copy_len = buffer_size - 1; // 预留一个字节用于字符串结束符
    }

    // 复制消息体到参数缓冲区
    memcpy(param_buffer, msg_body, copy_len);

    // 确保字符串以null结尾
    param_buffer[copy_len] = '\0';

    return copy_len; // 返回实际复制的字节数
}
